def count_good_triplets(arr, a, b, c):
    max_val = max(arr)
    bit = [0] * (max_val + 2)

    def update(i, delta):
        i += 1
        while i <= max_val + 1:
            bit[i] += delta
            i += i & (-i)

    def prefix(i):
        i += 1
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & (-i)
        return s

    def range_count(lo, hi):
        if lo > hi:
            return 0
        lo, hi = max(lo, 0), min(hi, max_val)
        if lo > hi:
            return 0
        return prefix(hi) - (prefix(lo - 1) if lo > 0 else 0)

    for x in arr:
        update(x, 1)

    n = len(arr)
    count = 0
    for j in range(n):
        update(arr[j], -1)                       # tree now represents positions > j
        for i in range(j):
            if abs(arr[i] - arr[j]) <= a:
                lo = max(arr[j] - b, arr[i] - c)
                hi = min(arr[j] + b, arr[i] + c)
                count += range_count(lo, hi)       # O(log maxValue) range count
    return count

